	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n, m int
	fmt.Fscan(reader, &n, &m)
	grid := make([][]int, n)
	for i := 0; i < n; i++ {
		grid[i] = make([]int, m)
		for j := 0; j < m; j++ {
			fmt.Fscan(reader, &grid[i][j])
		}
	}

	// Collect positions for each pair
	pairs := make(map[int][][]int)
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			num := grid[i][j]
			pairs[num] = append(pairs[num], []int{i, j})
		}
	}

	// For each pair, determine the minimal moves needed
	total := 0
	for num, positions := range pairs {
		// Check if already adjacent
		p1, p2 := positions[0], positions[1]
		dist := abs(p1[0]-p2[0]) + abs(p1[1]-p2[1])
		if dist == 1 {
			continue
		}
		// Find the minimal moves to make them adjacent
		// Try moving each shoe to adjacent positions
		minMoves := findMinMoves(grid, p1, p2, n, m)
		total += minMoves
		// Update grid to reflect the move (swap the two shoes)
		grid[p1[0]][p1[1]], grid[p2[0]][p2[1]] = grid[p2[0]][p2[1]], grid[p1[0]][p1[1]]
	}

	fmt.Println(total)
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func findMinMoves(grid [][]int, p1, p2 []int, n, m int) int {
	// Try moving p1 to all adjacent cells and see if it becomes adjacent to p2
	minMoves := 2
	for _, dir := range [4][2]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}} {
		nx, ny := p1[0]+dir[0], p1[1]+dir[1]
		if nx >= 0 && nx < n && ny >= 0 && ny < m {
			dist := abs(nx-p2[0]) + abs(ny-p2[1])
			if dist == 1 {
				minMoves = 1
				break
			}
		}
	}
	if minMoves == 1 {
		return 1
	}
	// Try moving p2 to all adjacent cells
	for _, dir := range [4][2]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}} {
		nx, ny := p2[0]+dir[0], p2[1]+dir[1]
		if nx >= 0 && nx < n && ny >= 0 && ny < m {
			dist := abs(nx-p1[0]) + abs(ny-p1[1])
			if dist == 1 {
				minMoves = 1
				break
			}
		}
	}
	if minMoves == 1 {
		return 1
	}
	// Otherwise, need to swap both
	return 2
}
