	var n, m int
	fmt.Fscan(in, &n, &m)
	grid := make([][]int, n)
	for i := 0; i < n; i++ {
		grid[i] = make([]int, m)
		for j := 0; j < m; j++ {
			fmt.Fscan(in, &grid[i][j])
		}
	}

	pairs := make(map[int][][2]int)
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			pairs[grid[i][j]] = append(pairs[grid[i][j]], [2]int{i, j})
		}
	}

	visited := make(map[[2]int]bool)
	var components int
	for _, coords := range pairs {
		a, b := coords[0], coords[1]
		if visited[a] || visited[b] {
			continue
		}
		ai, aj := a[0], a[1]
		bi, bj := b[0], b[1]
		if abs(ai-bi)+abs(aj-bj) == 1 {
			visited[a] = true
			visited[b] = true
		} else {
			components++
		}
	}
	fmt.Println(components)
}

