)

var n, m int
var grid [][]int
var pos [][2]int
var cnt int
var ans int

func main() {
	in := bufio.NewReader(os.Stdin)
	fmt.Fscan(in, &n, &m)
	grid = make([][]int, n)
	for i := 0; i < n; i++ {
		grid[i] = make([]int, m)
		for j := 0; j < m; j++ {
			fmt.Fscan(in, &grid[i][j])
		}
	}
	pos = make([][2]int, n*m+1)
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			pos[grid[i][j]] = [2]int{i, j}
		}
	}
	cnt = n * m / 2
	ans = 1 << 30
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			if grid[i][j] == 0 {
				continue
			}
			k := pos[grid[i][j]][0]*m + pos[grid[i][j]][1]
			if k == i*m+j {
				continue
			}
			grid[i][j], grid[k/m][k%m] = grid[k/m][k%m], grid[i][j]
			pos[grid[i][j]] = [2]int{i, j}
			pos[grid[k/m][k%m]] = [2]int{k / m, k % m}
			dfs(0, 0)
			grid[i][j], grid[k/m][k%m] = grid[k/m][k%m], grid[i][j]
			pos[grid[i][j]] = [2]int{i, j}
			pos[grid[k/m][k%m]] = [2]int{k / m, k % m}
		}
	}
	fmt.Println(ans)
}

func dfs(x, y int) {
	if x == n {
		ans = min(ans, cnt)
		return
	}
	if y == m {
		dfs(x+1, 0)
		return
	}
	if grid[x][y] == 0 {
		dfs(x, y+1)
		return
	}
	k := pos[grid[x][y]][0]*m + pos[grid[x][y]][1]
	if k == x*m+y {
		dfs(x, y+1)
		return
	}
	if k > x*m+y {
		cnt++
		grid[x][y], grid[k/m][k%m] = grid[k/m][k%m], grid[x][y]
		pos[grid[x][y]] = [2]int{x, y}
		pos[grid[k/m][k%m]] = [2]int{k / m, k % m}
		dfs(x, y+1)
		grid[x][y], grid[k/m][k%m] = grid[k/m][k%m], grid[x][y]
		pos[grid[x][y]] = [2]int{x, y}
		pos[grid[k/m][k%m]] = [2]int{k / m, k % m}
		cnt--
	}
	dfs(x, y+1)
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
